window.SS_KEYS_ADD("vi",{"est.fx.live2":"Tỷ giá hôm nay","est.fx.incl":"cập nhật mỗi ngày","est.fx.offline2":"Ước tính ngoại tuyến","est.fx.confirm":"tỷ giá chính xác được chốt trong báo giá bằng văn bản","gift.k.fee":"Phí styling","gift.k.credit":"Tín dụng trang phục","gift.k.arrives":"Bạn nhận","gift.k.begins":"Bắt đầu với","gift.1arr":"Một món đồ","gift.2arr":"Ba đến năm món","gift.4arr":"Tám đến mười hai món","gift.3arr":"Một buổi thử đồ — hoặc video trực tiếp","gift.1beg":"Một bản khảo sát phong cách ngắn","gift.2beg":"Một buổi tư vấn","gift.4beg":"Hồ sơ phong cách đầy đủ","gift.3beg":"Hồ sơ phong cách đầy đủ","ask.eyebrow":"Những câu hỏi thường gặp","ask.h2":"Thắc mắc, <em>được giải đáp</em>.","ask.intro":"Giải đáp thành thật về size, hải quan, giao hàng và tính chính hãng — và mình luôn sẵn sàng cho mọi câu hỏi khác chỉ sau một tin nhắn.","nav.about":"Giới thiệu","nav.services":"Dịch vụ","nav.process":"Quy trình","nav.estimate":"Ước tính","nav.gift":"Quà tặng","nav.lookbook":"Lookbook","nav.details":"Chi tiết","nav.contact":"Liên hệ","nav.directory":"Danh mục","dir.eyebrow":"Danh mục","dir.h2":"Danh mục Thời trang Sài Gòn","dir.lead":"Bản đồ sống về các nhà mốt của thành phố — 320 cửa hàng, atelier, nhãn thiết kế và chợ phiên đã xác minh, lọc theo quận, phân khúc và danh mục. Đây là nền tảng cho mọi yêu cầu tìm nguồn.","dir.s1":"thương hiệu","dir.s2":"tại Sài Gòn","dir.s3":"quận","dir.cta":"Khám phá 320 thương hiệu","dir.cta2":"Đọc cẩm nang mua sắm →","dir.legend":"nhà mốt — diện tích vòng tròn tỉ lệ với số lượng","dir.cap":"Diện tích vòng tròn tỉ lệ số lượng nhà mốt. 9 quận có 207 nhà; 43 nhà còn lại trực tuyến hoặc đa chi nhánh — tổng 250 tại Sài Gòn.","a11y.title":"Cài đặt","a11y.language":"Ngôn ngữ","a11y.textsize":"Cỡ chữ","a11y.theme":"Giao diện","theme.auto":"Tự động","theme.light":"Sáng","theme.dark":"Tối","theme.mono":"Đơn sắc","a11y.contrast":"Tương phản cao","a11y.motion":"Giảm chuyển động","hero.eyebrow":"Atelier tạo phong cách &amp; tìm nguồn tại Sài Gòn","hero.h1":"Phong cách Sài Gòn,<br/>giao đến mọi nơi.","hero.lead":"Tôi tìm nguồn những món thời trang và làm đẹp Việt Nam khó kiếm từ Thành phố Hồ Chí Minh cho khách hàng ở nước ngoài.","hero.lead2":"Mỗi món đều được chọn lựa kỹ lưỡng, tận tay kiểm tra và đánh giá độ vừa vặn trước khi rời khỏi Sài Gòn.","hero.cta1":"Bắt đầu yêu cầu","hero.cta2":"Quy trình ra sao","hero.assure":"Phản hồi kín đáo trong vòng 1–2 ngày làm việc.","hero.scroll":"Cuộn xuống","about.eyebrow":"Giới thiệu","about.h2":"Stylist của bạn tại Sài Gòn","about.intro":"Seraphic Styler là một atelier tư vấn phong cách và tìm nguồn riêng tại Thành phố Hồ Chí Minh, dành cho những người trân trọng cái đẹp, thời trang và văn hóa đương đại. Tôi tìm những món đồ Việt Nam thật sự độc bản và mang đến cho bạn qua một quy trình tỉ mỉ, thư thái và đầy tính cá nhân.","about.b1h":"Câu chuyện của tôi","about.b1":"Các thương hiệu của Sài Gòn mang một nét lãng mạn riêng: hiện đại, thanh lịch một cách kín đáo, và phần lớn vô hình bên ngoài thành phố. Những người bạn ở nước ngoài phải lòng vẻ đẹp ấy nhưng không có cách nào với tới. Tôi bắt đầu tìm nguồn cho họ — và đó vẫn là linh hồn của công việc này: giúp bạn khoác lên mình một mảnh Việt Nam được chăm chút — làm nên bằng chủ đích và chọn lựa bằng một ánh nhìn tinh tế.","about.b2h":"Cách tôi làm việc","about.b2":"Bạn chia sẻ một thương hiệu, một gợi ý tham khảo, hay đơn giản là cảm xúc bạn mong muốn cùng size của mình. Tôi đích thân đến tận nơi tìm nguồn, chụp ảnh chính món hàng thật, rồi tư vấn về dáng, tỷ lệ và đường hoàn thiện trước khi cùng quyết định mua. Những gì bạn thấy chính xác là những gì sẽ đến tay — giá cả trung thực, đóng gói cẩn thận, và được đồng hành kín đáo từ Sài Gòn đến tận cửa nhà bạn.","why.eyebrow":"Vì sao chọn Seraphic Styler","why.h2":"Hơn cả một đường dẫn sản phẩm","why.r1h":"Hiếm, nội địa, chính hãng","why.r1":"Tiếp cận những thương hiệu Việt không gửi hàng ra nước ngoài — những món nội địa thật sự mà bạn không thể mua từ bên ngoài đất nước.","why.r2h":"Được tạo phong cách, không chỉ chuyển tiếp","why.r2":"Một stylist song ngữ có mặt ngay tại Sài Gòn. Tôi tuyển chọn, tư vấn về form dáng, và tự mình dạo qua các boutique — không chỉ đơn thuần chuyển cho bạn một đường link.","why.r3h":"Báo giá trung thực &amp; bằng chứng","why.r3":"Bảng phân tích chi phí minh bạch trước khi mua bất cứ thứ gì, ảnh xác nhận chính món hàng thật, và mã vận đơn khi hàng được gửi đi — không có biên lợi nhuận ẩn nào.","services.eyebrow":"Dịch vụ","services.h2":"Chọn mức hỗ trợ bạn cần","services.intro":"Từ tìm nguồn một món riêng lẻ đến xây dựng cả một tủ đồ — cùng với làm đẹp kiểu Việt Nam. Hãy chọn điều phù hợp với bạn, gửi cho tôi vài dòng, và tôi sẽ xác nhận chi tiết cùng báo giá cuối cùng.","svc.1h":"Tìm nguồn thương hiệu Việt","svc.1b":"Dành cho: một món thuộc thương hiệu nội địa cụ thể bạn đã có trong đầu.\nTôi đến boutique, chụp ảnh chính món hàng thật, xác nhận giá và tình trạng còn hàng, rồi thay bạn sắp xếp việc mua và gửi hàng quốc tế.\nThời gian: xác nhận trong 1–3 ngày.\nBạn gửi: đường dẫn hoặc ảnh chụp, size, nơi nhận.","svc.2h":"Mua sắm cá nhân từ xa","svc.2b":"Dành cho: bạn biết phong cách, nhưng chưa rõ món cụ thể.\nTôi chuẩn bị một danh sách tuyển chọn ngắn gọn, súc tích kèm ảnh thật và giá, rồi mua món bạn chọn và gửi đi.\nThời gian: danh sách tuyển chọn trong 2–5 ngày.\nBạn gửi: cảm hứng, số đo, ngân sách, nơi nhận.","svc.7h":"Tìm nguồn làm đẹp Việt Nam","svc.7b":"Dành cho: chăm sóc da, mỹ phẩm và làm đẹp thảo dược made-in-Vietnam (gạo, sen, nghệ, cà phê).\nSản phẩm làm đẹp nội địa chính hãng — những thương hiệu hiếm khi bán ra nước ngoài — được tìm nguồn và gửi đi.\nThời gian: xác nhận trong 1–3 ngày.\nBạn gửi: tên sản phẩm hoặc ảnh chụp, nơi nhận. (Lưu ý: quy định về chất lỏng và hải quan khác nhau theo từng nước.)","svc.3h":"Tạo phong cách cho dịp &amp; sự kiện","svc.3b":"Dành cho: một đám cưới, một khoảnh khắc áo dài, một bữa tiệc, hay một buổi chụp hình.\nMột bộ trang phục trọn vẹn từ đầu đến chân (1–2 phương án) tìm nguồn theo dịp của bạn.\nThời gian: ý tưởng trong 3–5 ngày; vui lòng đặt sớm.\nTừ: một mức phí styling cố định (báo giá theo yêu cầu), được trừ vào đơn hàng của bạn.","svc.4h":"Tạo phong cách tủ đồ thường ngày","svc.4b":"Dành cho: một tủ đồ Sài Gòn linh hoạt, phối được với nhau.\nMột capsule được chọn để dễ layer cùng nhau, kèm ghi chú phối đồ.\nThời gian: lên kế hoạch trong 5–7 ngày, tìm nguồn theo từng giai đoạn.\nTừ: một mức phí styling capsule (báo giá theo yêu cầu).","svc.5h":"Lookbook / bảng phối đồ","svc.5b":"Dành cho: một kế hoạch trực quan trước khi bạn quyết định.\nMột bảng kỹ thuật số phối những món thật, còn hàng kèm giá và đường dẫn.\nThời gian: giao trong 3–5 ngày.\nTừ: một mức phí nhỏ mỗi bảng, được trừ toàn bộ nếu bạn đặt hàng.","services.cta":"Chưa chắc gói nào hợp với bạn? Hãy nhắn cho tôi vài dòng, tôi sẽ chỉ bạn nơi tốt nhất để bắt đầu.","sizing.eyebrow":"Kích cỡ &amp; dáng mặc","sizing.h2":"Kích cỡ Saigon, được chuyển ngữ","sizing.intro":"Ở Việt Nam, bảng size được xây trên một vóc dáng khác: nhỏ nhắn và mảnh mai là điểm khởi đầu. Một size medium kiểu phương Tây thường được dán nhãn XL, còn size large của Mỹ có thể đọc thành 2XL hay 3XL. Khoảnh khắc hơi giật mình khi nhìn nhãn ấy chỉ đơn giản là chuyện chuyển ngữ, không bao giờ là lời phán xét về cơ thể bạn.","sizing.b2":"Đọc hiểu bức tranh ấy là một phần công việc của tôi. Tôi biết những atelier ở Saigon nào cắt may rộng rãi, những nhãn hàng nào theo đúng kích cỡ châu Âu hay kích cỡ mở rộng, và nơi nào một món đồ sẽ tôn dáng tuyệt đẹp mà vẫn giữ trọn nét cá tính. Dù bạn mặc size small của Mỹ hay 5XL, tôi đều tìm được những lựa chọn dành cho vóc dáng cũng như gu thẩm mỹ của bạn.","sizing.vnxs":"<strong>VN XS &amp; VN S</strong> là những size nội địa nhỏ nhất — may cho dáng người nhỏ nhắn nhất, khoảng US 00–0 (UK 2–4 · EU 30–32) hoặc size teen/junior. Nếu size US XS thường rộng với bạn, đây có thể là khoảng size của bạn; nếu không, bạn thường bắt đầu từ VN M (xem bảng trên).","sizing.th1":"Size Mỹ bạn thường mặc","sizing.th2":"Nhãn Việt Nam tương đương","sizing.th3":"Điều nên biết","sizing.n1":"Khoảng size tiêu chuẩn ở hầu hết boutique Sài Gòn, nên lựa chọn ở đây phong phú nhất. Thường có dáng lửng, vai hẹp hơn và nách áo cao hơn — tôi lưu ý món nào ôm hoặc ngắn bất thường, và ghi chú món nào có thể chỉnh sửa.","sizing.n2":"Thường là size lớn nhất mà một cửa hàng thông thường có. Có nhãn lên size chuẩn chỉnh; có nhãn chỉ nới thêm bề ngang — tôi kiểm tra đường vai, dài tay và phần cạp tận nơi.","sizing.n3":"Hạn chế ở các cửa hàng phổ thông, nên tôi tìm nguồn từ những nhãn thực sự dựng rập cho khoảng size này, chứ không chỉ phóng to một mẫu.","sizing.n4":"Qua các nhãn chuyên biệt, thân thiện với mọi size — Himistore (đến 6XL, theo số đo châu Âu), Cow's House, và các nhà thiết kế cắt từ M đến 5XL cho vóc dáng quốc tế.","sizing.n5":"Phom giày trong nước thiên về dáng hẹp; dáng rộng hơn cần tìm nguồn riêng.","sizing.fabric":"Kích cỡ thay đổi theo thương hiệu và chất liệu — một món cotton từ local brand trẻ có thể nhỏ hơn hai size so với đồ linen của một atelier ảnh hưởng châu Âu. Áo dài và đồ may đo cắt ôm sát, ít co giãn. Tôi xác nhận số đo thực của trang phục trước khi chúng ta mua.","sizing.brands":"Với kích cỡ mở rộng, tôi duy trì mối quan hệ với những nhãn hàng như Himistore (lên đến 6XL, theo số đo châu Âu) và các boutique dành cho dáng đầy đặn như Cow's House, cùng một vài nhà thiết kế ở Saigon cắt may có chủ đích cho vóc dáng quốc tế, từ M đến 5XL. Bạn không bao giờ phải tự mình phỏng đoán.","sizing.cta":"Tìm trang phục đúng size của bạn →","sizing.fine":"Chi tiết nhỏ — size nhỏ nhất, chất liệu &amp; nhãn cỡ lớn","process.eyebrow":"Quy trình","process.h2":"Từ tin nhắn đầu tiên đến tận cửa nhà bạn","process.intro":"Một trình tự rõ ràng, được cân nhắc kỹ. Bạn xem và duyệt mọi thứ trước khi thanh toán toàn bộ. Bảng giá đầy đủ và thông tin vận chuyển nằm ở phần chi tiết bên dưới.","step.1h":"Yêu cầu","step.1b":"Gửi món bạn muốn — một đường dẫn, một ảnh chụp, hay một lời mô tả. Mới biết một thương hiệu? Tôi sẽ giúp bạn tìm. Bạn nhận được một nhận định chân thật về khả năng tìm nguồn món đó.","step.2h":"Bản tóm tắt phong cách","step.2b":"Hãy chia sẻ gu thẩm mỹ, size, ngân sách và nơi nhận hàng của bạn. Tôi ghi nhận sở thích về độ vừa vặn và màu sắc, đồng thời góp ý chân thành về những gì có thể hợp với bạn.","step.3h":"Tìm nguồn + ảnh xác nhận","step.3b":"Tôi tìm món hàng tận nơi và kiểm tra kỹ. Bạn nhận được ảnh thật của chính món hàng đó trước khi mọi việc tiếp tục.","step.4h":"Bạn duyệt","step.4b":"Xác nhận đúng là món bạn cần. Muốn màu khác hay size khác? Đây chính là lúc để điều chỉnh. Không gì được mua cho đến khi bạn đồng ý.","step.5h":"Đặt cọc &amp; thanh toán","step.5b":"Đặt cọc 50% để tiến hành đơn hàng; 50% còn lại cộng phí vận chuyển trước khi gửi đi. Thanh toán qua chuyển khoản ngân hàng, Wise, PayPal hoặc Payoneer — USDC theo yêu cầu. Xử lý trong 2–7 ngày.","step.6h":"Đóng gói &amp; gửi đi khắp thế giới","step.6b":"Tôi đóng gói cẩn thận và gửi đến khu vực của bạn. Bạn nhận được mã vận đơn ngay khi hàng lên đường.","step.7h":"Theo dõi sau giao hàng","step.7b":"Tôi hỏi thăm khi hàng đến nơi để chắc chắn mọi thứ hoàn hảo — và tôi luôn sẵn lòng giúp bạn phối đồ.","journey.eyebrow":"Hành trình, như một câu chuyện","journey.h2":"Từ giấc mơ đến tủ <em>đồ</em>","journey.intro":"Trọn vẹn hành trình chỉ trong một thoáng nhìn — năm nhịp nhẹ nhàng, từ một giấc mơ đến món đồ trong tay bạn.","journey.1h":"Bước vào","journey.1b":"Trong một giấc mơ dịu êm — thế giới lavender thanh khiết.","journey.2h":"Gặp gỡ","journey.2b":"Một người thật ở Sài Gòn — song ngữ và luôn hiện diện.","journey.3h":"Nhìn thấy","journey.3b":"Chính xác món bạn sẽ nhận — được chụp ảnh, được kiểm chứng.","journey.4h":"Tin tưởng","journey.4b":"Một quy trình minh bạch — giá trung thực, mã vận đơn, sự chăm chút.","journey.5h":"Khoác lên","journey.5b":"Một món đồ Việt Nam đầy tinh tế, ở bất cứ nơi đâu trên thế giới.","est.badge":"Chỉ là ước tính","est.h2":"Lập bảng ước tính sơ bộ","est.intro":"Một con số tương đối có cơ sở — không phải thanh toán. Thêm các món, chọn nơi nhận, và tôi sẽ xác nhận báo giá chính xác qua tin nhắn. Dịch vụ styling và thử đồ tại cửa hàng được đặt riêng.","est.items.h":"Các món của bạn","est.items.note":"Nhập giá cửa hàng của từng món bằng VND.","est.add":"Thêm món","est.shipto":"Chọn điểm đến của bạn","est.q.dest":"Chọn khu vực gần nhà bạn nhất — tôi giao hàng đến mọi nơi trên thế giới.","est.deposit":"Đặt cọc — thanh toán để bắt đầu","est.deposit.tip":"Gồm các món đồ, phí dịch vụ và phí cơ bản — tất cả những gì tôi có thể tính chính xác hôm nay. Thanh toán sau khi bạn duyệt ảnh thật, để tôi đi mua đồ.","est.balance":"Phần còn lại — trước khi gửi hàng","est.balance.tip":"Chỉ là phí vận chuyển, gửi cho bạn sau khi kiện hàng đã đóng gói và cân — nên bạn trả đúng giá vận chuyển thật, không phải ước đoán.","est.compare":"So sánh thêm một điểm đến","est.compare.tip":"Nếu món đồ có thể gửi đến nhiều địa chỉ — nhà thứ hai, người thân ở nước ngoài, hoặc nơi bạn đang ở tháng đó — hãy chọn cả hai để xem hai tổng chi phí cạnh nhau. Phí vận chuyển là phần thay đổi nhiều nhất trong mọi ước tính.","est.shipto2":"Điểm đến thứ hai","est.q.dest2":"Tôi sẽ báo giá cả hai tuyến và bạn quyết định sau khi thấy giá vận chuyển thực tế.","est.cmp.h":"So sánh hai điểm đến","est.cmp.sub":"Cùng món đồ, cùng phí dịch vụ — chỉ phí vận chuyển thay đổi. Chọn một, hoặc gửi cả hai để tôi xác nhận giá vận chuyển thực tế cho từng tuyến.","est.cmp.lower":"Ước tính thấp hơn","est.cmp.use":"Gửi về đây","est.cmp.cheaperby":"rẻ hơn khoảng","est.cmp.even":"Hai tuyến ước tính bằng nhau — chọn nơi nào tiện nhận hơn cho bạn.","est.cmp.duty":"Thuế nhập khẩu và hải quan tại nước nhận chưa được tính và khác nhau tùy quốc gia — tuyến rẻ hơn vẫn có thể tốn kém hơn sau thuế. Tôi sẽ báo bạn trước khi thanh toán.","est.cmp.custom":"Kiện trên 10 kg được báo giá riêng, nên tôi sẽ tính tay cả hai tuyến — hãy gửi ước tính và tôi sẽ báo giá {a} và {b} cùng lúc.","est.cmp.nopieces":"Phí vận chuyển được thêm khi các món đồ đã được tìm mua — hãy thêm một món để so sánh hai tuyến.","ship.r3":"Mỹ / Canada","ship.r6":"Mỹ Latinh","ship.r4":"Châu Âu / Anh","ship.r2":"Úc / New Zealand","ship.r1":"Đông &amp; Đông Nam Á","ship.r7":"Nam &amp; Trung Á","ship.r5":"Trung Đông &amp; Bắc Phi","ship.r8":"Châu Phi","est.weight":"Trọng lượng kiện hàng ước tính","est.w.light":"Nhẹ — 0.5–3 kg / 1–6.6 lb","est.w.standard":"Tiêu chuẩn — 3–10 kg / 6.6–22 lb","est.w.heavy":"Nặng — 10–20 kg / 22–44 lb (báo giá riêng)","est.w.haul":"Đơn lớn — 20 kg+ / 44 lb+ (báo giá riêng)","est.q.weight":"Ước chừng là được — tôi sẽ xác nhận trọng lượng chính xác trước khi gửi hàng. Phí chuyển phát quốc tế cho quần áo không hề rẻ: một kiện 0,5–1 kg gần đây tốn 1.950.000₫, và vải dày nặng hơn vẻ ngoài.","est.complex":"Tìm nguồn hiếm / phức tạp (+200.000₫)","est.complex.tip":"Chỉ áp dụng cho hàng hiếm hoặc bản giới hạn, phải tìm ở nhiều cửa hàng khắp thành phố, thời hạn gấp, hoặc nhiều thay đổi sau khi đã bắt đầu tìm — luôn được thống nhất trước với bạn, không bao giờ bất ngờ.","est.result.h":"Tổng ước tính","est.sub":"Tạm tính tiền hàng","est.fee":"Phí dịch vụ","est.fee.tip":"Phí tìm nguồn của tôi cho mỗi món: 150,000₫ cho món dưới 2,000,000₫, 8% cho mức 2–5,000,000₫, và 7% cho mức cao hơn. Đã bao gồm phí vận chuyển nội địa trong nước Việt Nam.","est.base":"Phí cơ bản","est.base.tip":"Phí cố định 100,000₫ cho mỗi đơn hàng, bao gồm việc điều phối, trao đổi tin nhắn và đóng gói cẩn thận. Phí vận chuyển được tính theo đúng chi phí thực tế.","est.complexline":"Tìm nguồn phức tạp","est.green":"Mua sắm xanh — chọn thương hiệu bền vững (giảm 10% phí dịch vụ)","est.green.tip":"Mua sắm xanh có ý nghĩa lớn: chọn đồ ít tác động, sản xuất địa phương và tuần hoàn giúp giảm rác thải, tiết kiệm nước và ủng hộ nghệ nhân Việt Nam. Chọn một thương hiệu bền vững đã xác minh và mình giảm 10% phí dịch vụ. Tìm hiểu thêm về lối sống xanh tại treehugger.com.","est.greenline":"Ưu đãi mua sắm xanh","est.shiplbl":"Phí vận chuyển ước tính","est.total":"Tổng cộng (VND)","est.usd":"Khoảng tương đương","est.send":"Gửi bảng ước tính này để xác nhận","est.copied":"✓ Đã sao chép tóm tắt giỏ hàng — dán vào tin nhắn gửi cho tôi.","est.note":"Đây là ước tính. Báo giá cuối cùng của bạn (phí vận chuyển chính xác, tình trạng còn hàng, giá cửa hàng) sẽ được tôi xác nhận trước khi có bất kỳ khoản thanh toán nào.","est.q.result":"Một con số tổng quát — bạn có thể chụp màn hình hoặc so sánh với báo giá cuối cùng.","est.back":"Quay lại","est.next":"Tiếp tục","est.see":"Xem ước tính của tôi","est.restart":"Bắt đầu lại","look.eyebrow":"Lookbook","look.h2":"Tác phẩm chọn lọc","look.intro":"Những món thời trang Việt đang được ưa chuộng, tạo phong cách và tìm nguồn cho khách hàng khắp thế giới. Ảnh lookbook của riêng bạn sẽ được đặt thẳng vào những khung này.","look.t1":"Áo dài cách tân","look.t2":"Coquette / soft girl","look.t3":"Từ công sở đến buổi tối","look.t4":"Linen &amp; tối giản","look.t5":"Tìm món vintage","look.t6":"Trang phục dự tiệc","trust.eyebrow":"Được tin tưởng âm thầm","trust.h2":"Đặt hàng từ nước ngoài cần một sự tin tưởng nhất định","trust.intro":"Tôi giữ mọi thứ thật giản đơn: tôi cho bạn xem món hàng thật trước khi bạn thanh toán, gửi mã vận đơn khi hàng đi, và luôn nhắn tin với bạn bằng ngôn ngữ của bạn suốt chặng đường.","trust.s1h":"Bạn được thấy trước","trust.s1b":"Ảnh xác nhận chính món hàng thật trước khi bạn thanh toán. Những gì bạn thấy chính xác là thứ sẽ đến tay.","trust.s2h":"Theo dõi suốt hành trình","trust.s2b":"Một mã vận đơn ngay khi kiện hàng được gửi đi, kèm cập nhật cho đến khi đến tận cửa nhà bạn.","trust.s3h":"Một con người thật ở Sài Gòn","trust.s3b":"Song ngữ, có mặt tận nơi, tự mình dạo qua các boutique — không phải một tài khoản bán lại vô danh.","gift.eyebrow":"Quà tặng phong cách","gift.h2":"Trao tặng món quà tủ đồ Sài Gòn","gift.intro":"Cho một dịp sinh nhật, một lễ cưới, hay đơn giản chỉ vì muốn dành tặng — hãy chọn một hạng quà hoặc tự định mức số tiền của riêng bạn, tôi sẽ đích thân chăm sóc người nhận, rồi gửi đến họ một lời nhắn cùng mã để sử dụng.","gift.1h":"Khởi Đầu","gift.1b":"Một khoản tín dụng cho một món đồ mà người nhận tự chọn, do tôi tìm và gửi đến. Một cử chỉ nhỏ xinh, sang trọng một cách kín đáo.","gift.buy":"Tặng gói này","gift.tag":"Được yêu thích nhất","gift.2h":"Bộ Sưu Tuyển","gift.2b":"Chúng tôi khởi đầu bằng một buổi tư vấn, sau đó tôi tuyển chọn một bộ sưu tập nhỏ gồm ba đến năm món đúng kích cỡ của họ — gửi đến bất cứ nơi đâu họ đang ở.","gift.3h":"Trọn Atelier","gift.3b":"Trọn vẹn trải nghiệm, trực tiếp tận nơi: tư vấn phong cách, tìm nguồn trang phục và thử đồ tại cửa hàng, dành cho một dịp xứng đáng với đôi chút nghi thức trang trọng.","gift.included":"Mỗi món quà bao gồm dịch vụ tư vấn phong cách và tìm nguồn của tôi, cùng một khoản tín dụng dành cho chính các trang phục. Phí vận chuyển sẽ được báo giá khi người nhận sử dụng quà.","gift.pay":"Muốn chia nhỏ chi phí? PayPal Pay Later cho phép bạn thanh toán thành nhiều đợt, ở những nơi có hỗ trợ.","gift.any":"Hoặc tặng quà với số tiền tùy ý →","gift.cur":"Hiển thị giá bằng","gift.redeem":"Bạn có mã quà tặng? Đổi ngay →","gift.note":"Thanh toán bằng thẻ ngay trên trang bảo mật của Stripe, hoặc nhắn cho mình để chuyển khoản ngân hàng, Wise, PayPal hoặc Payoneer — USDC theo yêu cầu. Mỗi món quà đều kèm một lời nhắn kỹ thuật số.","gift.season":"Mùa Sài Gòn khép lại ngày 18 tháng 8 — hãy tặng trước ngày 1 tháng 8 để người nhận kịp đổi quà trước ngày 8 và kiện hàng bay trước ngày 15. Quà tặng muộn hơn sẽ được trân trọng thực hiện vào mùa sau.","gift.1s":"$15 phí tư vấn · $34 tín dụng trang phục ≈ 900.000₫","gift.2s":"$45 phí tư vấn · $104 tín dụng trang phục ≈ 2.700.000₫","gift.3s":"$110 phí tư vấn · $239 tín dụng trang phục ≈ 6.300.000₫","gift.1b2":"Một cuộc trò chuyện ngắn về phong cách, rồi tôi tìm một món đồ họ sẽ yêu thích — kiểm chứng tận nơi, chụp ảnh để họ duyệt, rồi gửi đi. Một cử chỉ nhỏ xinh, sang trọng một cách kín đáo.","gift.2b2":"Chúng ta bắt đầu bằng một buổi tư vấn, sau đó tôi tuyển chọn một bộ sưu tập nhỏ đúng kích cỡ của họ theo giá trị khoản tín dụng — thường là ba đến năm món từ các nhà thiết kế Sài Gòn, ít hơn nếu họ phải lòng một món hiếm hơn.","gift.3b2":"Trọn vẹn trải nghiệm, trực tiếp tại Sài Gòn: một buổi tư vấn, tìm nguồn trang phục và hai giờ thử đồ tại cửa hàng. Trang phục thường được mang về ngay trong ngày — không cần vận chuyển.","gift.included2":"Mỗi món quà được tách bạch minh bạch, đúng tinh thần định giá trung thực: một khoản phí cố định cho công tư vấn và tìm nguồn, cùng một khoản tín dụng cố định dành cho chính các trang phục. Đây chính xác là nơi từng khoản được dùng.","gift.terms":"Mã quà tặng được gửi trong vòng 24 giờ sau khi thanh toán, đổi qua email hoặc tin nhắn, và có hiệu lực trong mùa Sài Gòn hiện tại — có thể gia hạn sang mùa sau, chỉ cần ngỏ lời.","eco.eyebrow":"Tìm nguồn có ý thức","eco.h2":"Đẹp, và tử tế hơn một chút","eco.intro":"Chậm rãi hơn vội vàng, gần gũi hơn xa xôi, sửa chữa hơn thay mới. Khi bạn mong muốn, tôi sẽ dẫn bạn đến những nhà sản xuất tâm huyết nhất của Việt Nam — và luôn cố gắng tìm nguồn ít tác động đến môi trường trong khả năng của mình.","eco.1h":"Xe điện, ít kiện hơn","eco.1b":"Những chuyến đi tìm nguồn của tôi trong Sài Gòn đều dùng xe điện qua Xanh SM / Green SM — không khí thải. Gộp đơn hàng của bạn vào một kiện duy nhất giúp giảm số lần gửi và giảm lượng carbon khi vận chuyển.","eco.2h":"Thương hiệu Việt có ý thức","eco.2b":"Tôi sẽ chỉ cho bạn những thương hiệu bền vững hàng đầu Việt Nam — sợi hữu cơ và tự nhiên, cắt may không lãng phí, nhuộm tự nhiên, chuỗi cung ứng thủ công — kèm một khoản giảm nhỏ phí dịch vụ khi bạn chọn một thương hiệu bền vững đã được xác minh.","eco.3h":"Tuần hoàn &amp; vintage","eco.3b":"Thích mua sắm tuần hoàn? Tôi tìm nguồn hàng secondhand và vintage cao cấp từ những cửa hàng đồ cũ được tuyển chọn kỹ nhất Sài Gòn, và có thể kết hợp với một thợ may đáng tin để sửa chữa và chỉnh size.","eco.more":"Xem các thương hiệu có ý thức, đạo đức &amp; bài đọc thêm bên dưới","details.eyebrow":"Chi tiết","details.h2":"Mọi thứ, khi bạn sẵn sàng","acc.pricing":"Giá &amp; phí","price.formula":"Giá món hàng = Giá cửa hàng + Phí cơ bản + Phí dịch vụ + Phí vận chuyển quốc tế","price.formula.detail":"Giá cửa hàng — trả cho boutique\nPhí cơ bản — điều phối, xử lý &amp; đóng gói (100.000₫ mỗi đơn)\nPhí dịch vụ — tìm nguồn &amp; vận chuyển nội địa trong Việt Nam (mỗi món, bên dưới)\nPhí vận chuyển quốc tế — chi phí chuyển phát từ Sài Gòn đến bạn (theo giá gốc)","tier.1r":"Món dưới 2.000.000₫","tier.1s":"cố định, mỗi món","tier.2r":"Món 2–5.000.000₫","tier.2s":"mỗi món","tier.3r":"Món trên 5.000.000₫","tier.3s":"mỗi món","price.base.h":"Phí cơ bản · 100.000₫ / đơn","price.base.b":"Một khoản phí cố định mỗi đơn cho việc nhắn tin, điều phối và đóng gói cẩn thận. Phí vận chuyển được tính theo giá gốc — không cộng biên lợi nhuận ẩn nào.","price.complex.h":"Tìm nguồn phức tạp · + từ 200.000₫","price.complex.b":"Chỉ cộng thêm với những đợt hàng hiếm hoặc giới hạn, săn lùng nhiều cửa hàng, thời hạn gấp, hoặc nhiều thay đổi sau khi đã bắt đầu tìm nguồn. Được thống nhất trước với bạn.","price.min":"Một mức tối thiểu mềm: hầu hết đơn hàng vào khoảng 100–150 USD+ (hoặc vài món) để trải nghiệm xứng đáng cho cả hai bên. Bạn luôn được xem bảng phân tích chi phí rõ ràng trước khi mua bất cứ thứ gì.","t2.1h":"Mua sắm cá nhân tiêu chuẩn","t2.1b":"Đơn hàng online gửi đến bạn. Phí cơ bản + phí dịch vụ mỗi món, đã bao gồm vận chuyển nội địa Việt Nam. Cách đặt hàng thường ngày.","t2.2h":"Thử đồ &amp; canh form tại cửa hàng","t2.2b":"Để bạn yên tâm hơn trước khi mua, tôi đến tận boutique — lấy các size, giám sát buổi thử đồ, và gửi ghi chú form dáng cùng ảnh trực tiếp. 500,000₫/giờ, tối thiểu 2 giờ, kèm khoản cọc 500,000₫ để giữ lịch (được trừ vào buổi làm việc). Rất phù hợp cho những đơn cần chuẩn form hoặc giá trị cao (dự chi ~200–300 USD+).","t2.3h":"Đơn phức tạp / cần chăm chút nhiều","t2.3b":"Yêu cầu hiếm, gấp về thời gian, hoặc qua nhiều cửa hàng. Phí tiêu chuẩn cộng phí phức tạp (cố định hoặc một khoản phần trăm nhỏ thêm), luôn được thống nhất trước. Một khoản cọc giữ chỗ không hoàn lại để đảm bảo cho những đơn nghiêm túc.","acc.shipping":"Vận chuyển &amp; hải quan","ship.intro":"Các kiện nhỏ có thể ước tính từ bảng hướng dẫn bên dưới. Với những đơn gộp lớn hơn, phí vận chuyển cuối cùng phụ thuộc vào trọng lượng sau đóng gói, kích thước và nơi nhận. Với đơn nặng — từ 10kg+ / 22lb+ — tôi xác nhận phương án đóng gói tốt nhất và báo giá chuyển phát trước khi gửi, và có thể tách thành nhiều thùng khi điều đó an toàn hoặc tiết kiệm hơn.","shipcl.h1":"Hạng","shipcl.h2":"Trọng lượng","shipcl.h3":"Cách tôi xử lý","shipcl.1a":"Nhẹ","shipcl.1c":"Ước tính tức thì theo bảng (bên dưới).","shipcl.2a":"Tiêu chuẩn","shipcl.2c":"Khoảng ước tính; chi phí cuối theo trọng lượng &amp; kích thước sau đóng gói.","shipcl.3a":"Nặng","shipcl.3c":"Báo giá riêng sau khi gộp &amp; đo đạc.","shipcl.4a":"Đơn lớn","shipcl.4c":"Tách kiện hoặc xử lý theo kiểu vận tải hàng.","ship.th1":"Khu vực","ship.thL":"Nhẹ · 0.5–3kg","ship.thS":"Tiêu chuẩn · 3–10kg","ship.heavy":"Đơn nặng (từ 10kg+) và đơn lớn được báo giá riêng sau khi tôi lên phương án đóng gói — không bao giờ đoán mò. Trọng lượng tính phí có thể là trọng lượng thực hoặc trọng lượng quy đổi (L×W×H ÷ 5000).","shipn.1h":"Mặc định gộp đơn","shipn.1b":"Tôi gom tất cả các món của bạn từ nhiều thương hiệu vào một kiện trước khi gửi quốc tế — ít phí hơn, một mã vận đơn.","shipn.2h":"Đóng gói lại để giảm thể tích","shipn.2b":"Đơn vị chuyển phát có thể tính phí theo kích thước, không chỉ trọng lượng. Tôi đóng gói lại để cắt bớt phần cồng kềnh thừa, để bạn không phải trả tiền cho không khí.","shipn.3h":"Tách kiện khi hợp lý hơn","shipn.3b":"Với những đơn rất nặng hoặc dễ vỡ, tôi có thể tách thành nhiều thùng khi điều đó an toàn hoặc tiết kiệm hơn — bạn quyết định sau khi tôi đưa ra các phương án.","ship.assure":"Tôi sẽ báo trước bất kỳ rủi ro bất thường nào về hải quan hoặc đơn vị vận chuyển trước khi bạn quyết định. Thuế và lệ phí hải quan tùy theo quốc gia của bạn và do người nhận chi trả.","ship.green":"Khi kiện hàng của bạn bay cùng DHL, tôi chọn thêm GoGreen Plus — nhiên liệu hàng không bền vững (SAF) giúp giảm khoảng 30% khí thải của chuyến bay. Mọi đơn hàng đều được gói bằng bao bì giấy tái chế với băng keo giấy, và được gom chung để ít kiện hàng phải bay hơn — chi phí này tôi chịu, không bao giờ xuất hiện trên hóa đơn của bạn.","acc.faq":"Câu hỏi thường gặp","faq.q1":"Làm sao để chọn đúng size?","faq.a1":"Cho tôi biết số đo thường dùng của bạn và tôi sẽ kiểm tra bảng size của từng thương hiệu giúp bạn. Size Việt Nam thường nhỏ hơn, nên tôi sẽ nói thật điều đó với bạn. Quyết định cuối cùng là của bạn, nhưng tôi sẽ đưa ra nhận định tốt nhất trước khi chúng ta đặt hàng.","faq.q2":"Ai trả thuế và lệ phí hải quan?","faq.a2":"Mọi khoản thuế, lệ phí hải quan hay phí nhập khẩu đều do người nhận chi trả và không nằm trong tổng chi phí của bạn. Từ năm 2025, Mỹ áp thuế nhập khẩu với mọi kiện hàng bất kể giá trị; phần lớn các nước khác chỉ thu thuế trên một ngưỡng nhất định. Tôi luôn khai báo trung thực và cho bạn biết trước mức phí dự kiến ở nước bạn trước khi bạn thanh toán phần còn lại — con số cuối cùng luôn do hải quan nước bạn quyết định, không phải do tôi.","faq.q3":"Vận chuyển mất bao lâu?","faq.a3":"Khoảng 3 đến 21 ngày, tùy khu vực và dịch vụ bạn chọn. Đông &amp; Đông Nam Á nhanh nhất; các nơi còn lại chậm nhất. Bạn nhận được mã vận đơn khi kiện hàng được gửi đi.","faq.q4":"Các món có chính hãng không?","faq.a4":"Có. Tôi mua trực tiếp từ các thương hiệu và boutique Việt Nam tận tay, ngay tại Sài Gòn. Bạn nhận đúng món nội địa thật, tìm nguồn tận gốc — không bao giờ hàng giả.","faq.q5":"Nếu không vừa thì sao?","faq.a5":"Tôi là người mua sắm cá nhân, nên một size chọn sai khi đặt hàng không thể trả lại được — chính vì vậy tôi giúp bạn chọn đúng size từ trước. Nếu bạn muốn, tôi có thể hỏi boutique về phương án đổi hàng trước khi chúng ta mua.","faq.q6":"Thanh toán có an toàn không?","faq.a6":"Có. Thanh toán qua chuyển khoản ngân hàng, Wise, PayPal hoặc Payoneer — chọn PayPal Goods &amp; Services nếu bạn muốn được bảo vệ người mua. USDC (một stablecoin được quản lý) có sẵn theo yêu cầu, và nếu không phương thức nào tiện cho bạn, hãy nhắn tôi và tôi sẽ gợi ý một lựa chọn uy tín cho quốc gia của bạn. Đặt cọc 50% để đặt hàng, sau đó 50% còn lại cộng phí vận chuyển trước khi kiện hàng được gửi đi. Tôi gửi ảnh xác nhận từng món trước khi giao.","faq.q7":"Bạn có thể tìm nguồn những gì?","faq.a7":"Bất kỳ thương hiệu hay boutique nội địa Việt Nam nào, kể cả những món không đăng ở đây — cả thời trang lẫn làm đẹp: áo dài cách tân, coquette, dịu dàng nữ tính, vintage, chăm sóc da &amp; mỹ phẩm. Gửi một đường dẫn hoặc ảnh chụp và tôi sẽ tìm.","faq.q8":"Tôi có thể trả lại một món không?","faq.a8":"Chỉ khi gửi nhầm món hoặc hàng đến nơi bị hư hỏng. Liên hệ tôi trong vòng 48 giờ kèm video mở hộp đầy đủ, món chưa sử dụng còn nguyên tag; phí gửi trả do bạn chịu. Không chấp nhận: vài sợi chỉ thừa nhỏ, lệch màu nhẹ, mùi nhẹ, chọn sai size, hoặc phai màu sau khi giặt.","faq.q9":"Bạn có gửi đến nước tôi không?","faq.a9":"Gần như chắc chắn là có — tôi gửi hàng khắp thế giới. Không chắc về nước bạn? Nhắn tin cho tôi và tôi sẽ xác nhận.","faq.q10":"Tôi có thể thanh toán trả góp không?","faq.a10":"Có — quà tặng và đơn hàng lớn có thể chia thành nhiều đợt với PayPal Pay Later (Pay in 4), ở những nơi dịch vụ này khả dụng tại quốc gia của bạn.","acc.policies":"Chính sách &amp; tiền cọc","pol.1h":"Thanh toán &amp; đặt cọc","pol.1b":"Chuyển khoản ngân hàng, Wise, PayPal hoặc Payoneer; USDC có sẵn theo yêu cầu. Đặt cọc 50% để đặt hàng; 50% còn lại cộng phí vận chuyển trước khi gửi đi. Xử lý trong 2–7 ngày kể từ khi đặt cọc. Vì mỗi đơn được tìm riêng cho bạn, các giao dịch đã xác nhận là cuối cùng.","pol.2h":"Đổi trả &amp; hoàn tiền","pol.2b":"Tôi mua và gửi hàng thay bạn và gửi ảnh xác nhận trước. Chỉ trả lại nếu gửi nhầm món hoặc hàng đến nơi bị hư hỏng: liên hệ trong vòng 48h kèm video mở hộp đầy đủ, chưa sử dụng còn nguyên tag; phí gửi trả do bạn chịu. Công việc styling theo yêu cầu riêng không hoàn lại một khi đã bắt đầu.","pol.3h":"Giới hạn tìm nguồn","pol.3b":"Tôi có thể tìm nguồn gần như bất kỳ thương hiệu Việt nào, nhưng tôi không trữ hàng và tình trạng còn hàng tại địa phương thay đổi rất nhanh. Tôi xác nhận một món còn hàng trước khi nhận thanh toán cuối. Nếu hết hàng, tôi sẽ báo bạn ngay và gợi ý phương án thay thế gần nhất.","pol.4h":"Thời gian vận chuyển","pol.4b":"Trên toàn thế giới, thường 3–21 ngày tùy khu vực và dịch vụ. Bạn nhận được mã vận đơn khi hàng được gửi. Tôi không thể kiểm soát sự chậm trễ do thương hiệu, đơn vị vận chuyển hay hải quan gây ra.","pol.5h":"Trách nhiệm về hải quan","pol.5b":"Thuế, lệ phí hải quan hay phí nhập khẩu do người nhận chi trả và không nằm trong báo giá của bạn. Quy định khác nhau theo từng nước — Mỹ hiện áp thuế với mọi kiện hàng bất kể giá trị, trong khi nhiều nước khác chỉ thu thuế trên một ngưỡng nhất định. Tôi luôn khai báo kiện hàng trung thực và báo trước mức phí dự kiến ở nước bạn trước khi đến hạn thanh toán phần còn lại.","pol.6h":"Tính chính hãng","pol.6b":"Tôi tìm nguồn trực tiếp từ cửa hàng chính hãng và các boutique nội địa đáng tin cậy — không bao giờ hàng giả. Những gì bạn đặt là món thương hiệu nội địa chính hãng, và tôi rất sẵn lòng cho bạn biết mỗi món đến từ đâu.","pol.7h":"Đơn nghiêm túc &amp; tiền cọc","pol.7b":"Những dịch vụ cần chăm chút nhiều — thử đồ tại cửa hàng, tìm nguồn phức tạp, yêu cầu gấp — sẽ cần một khoản cọc nhỏ trước khi tôi bắt đầu. Khoản này chỉ đơn giản để dành riêng thời gian cho bạn và được trừ vào tổng tiền cuối cùng. Tiền cọc thường không hoàn lại một khi việc lên kế hoạch hoặc tìm nguồn đã bắt đầu; với thông báo trước 48 giờ, tôi luôn vui lòng dời lịch một lần. Nếu một yêu cầu trở nên lớn hơn nhiều so với mô tả ban đầu, tôi sẽ nhẹ nhàng báo giá phần phát sinh trước khi tiếp tục.","risk.1h":"Những điều có thể thay đổi","risk.1b":"Form dáng chính xác giữa các thương hiệu, còn hàng vào thời điểm đặt, kết quả vận chuyển/hải quan, tìm lại một món đã bán hết, hay sửa đổi không giới hạn. Điều tôi cam kết: một bức ảnh của mỗi món trước khi gửi đi, một nhận định chân thành về form dáng, và mã theo dõi khi hàng lên đường.","risk.2h":"Trước khi bạn mua","risk.2b":"Màu sắc khác nhau trên mỗi màn hình. Size của các thương hiệu không đồng nhất. Những món giới hạn có thể bán hết trước khi thanh toán hoàn tất. Đơn vị vận chuyển có thể làm chậm kiện hàng. Hải quan tùy thuộc nơi nhận của bạn. Ảnh cảm hứng dẫn dắt phong cách — chứ không phải một món y hệt.","risk.3h":"Những yêu cầu tôi có thể không nhận","risk.3b":"Thời hạn gấp phi thực tế mà tôi không thể đáp ứng một cách chu đáo, bất cứ thứ gì là hàng giả, và bất cứ điều gì không an toàn hay phi đạo đức. Nếu một yêu cầu không phù hợp, tôi sẽ nói với bạn một cách tử tế và chỉ cho bạn lựa chọn tốt hơn nếu có thể.","acc.notes":"Ghi chú phong cách","ed.1h":"Vì sao chọn thương hiệu Việt","ed.1b":"Một góc nhìn bạn hiếm khi tìm thấy ở nơi khác: form may cho cơ thể thật, giá hợp lý sát với gốc, và tay nghề thầm lặng — đường may sạch, vải tự nhiên mềm mại. Áo dài hiện đại, coquette dịu dàng, linen tối giản, vintage Sài Gòn. Hầu hết chỉ bán trong Việt Nam, bằng VND — chính khoảng cách đó là điều tôi lấp đầy.","ed.2h":"Tôi tạo phong cách tốt nhất cho ai","ed.2b":"Tôi đặc biệt hợp với những tủ đồ lãng mạn, coquette, tối giản, công sở, dự tiệc và vintage — hay một sự pha trộn tinh tế. Chưa chắc mình thuộc nhóm nào? Hãy gửi vài tấm hình bạn yêu thích, tôi sẽ đọc ra sợi chỉ kết nối chúng.","ed.3h":"Hãy gửi cho tôi những gì","ed.3b":"Đường dẫn hoặc ảnh chụp món bạn muốn · số đo của bạn (vòng ngực, eo, hông, chiều cao) · một món bạn có mà mặc vừa · dịp dùng · màu bạn yêu thích và muốn tránh · khoảng ngân sách của bạn. Chỉ cần một cảm hứng và một số đo cũng đủ để bắt đầu.","ed.4h":"Ghi chú về size &amp; form","ed.4b":"Size Việt Nam nhỏ hơn US/EU và khác nhau theo từng thương hiệu, nên tôi không đoán mò. Tôi khớp bảng size của thương hiệu với số đo của bạn — chứ không theo một chữ cái — và xác nhận số đo thực của trang phục khi chưa rõ. Bạn luôn được xem ảnh xác nhận trước khi gửi hàng.","ed.5h":"Không đăng ở đây? Tôi vẫn có thể tìm nguồn","ed.5b":"Những gì bạn thấy chỉ là một phần nhỏ. Nếu một thương hiệu bán trong Việt Nam, tôi thường có thể tìm được — bộ sưu tập mới của một boutique, một đợt nhập lại, một chiếc áo dài hiện đại, một món vintage bắt gặp trên TikTok, hay một sản phẩm làm đẹp khó tìm. Ranh giới trung thực: không hàng giả, không hứa hẹn về món đã hết hẳn, và tôi xác nhận giá cùng tình trạng còn hàng trước khi bạn thanh toán.","acc.legal":"Quyền riêng tư &amp; điều khoản","legal.privacy.h":"Quyền riêng tư","legal.privacy.b":"Những thông tin bạn chia sẻ — tên, email, số đo, ảnh, địa chỉ — chỉ dùng để tìm nguồn cho đơn hàng và trả lời bạn. Chúng không bao giờ được chia sẻ hay bán đi. Hãy nhắn tôi bất cứ lúc nào để xóa thông tin của bạn.","legal.terms.h":"Điều khoản","legal.terms.b":"Seraphic Styler là một dịch vụ mua sắm và tạo phong cách cá nhân: tôi mua và gửi hàng thay bạn. Ước tính không phải hóa đơn cuối cùng; một đơn hàng được xác nhận khi bạn duyệt và thanh toán. Tình trạng còn hàng, giá cả và tỷ giá có thể thay đổi cho đến khi được xác nhận. Khi đặt hàng, bạn chấp nhận các chính sách trên.","acc.eco":"Bền vững &amp; đạo đức","eco.ethics.h":"Đạo đức &amp; cam kết chống nô lệ hiện đại","eco.ethics.b":"Tôi chỉ tìm nguồn từ những thương hiệu chính danh, cửa hàng chính hãng và các boutique đáng tin cậy — không bao giờ hàng giả, và không bao giờ từ những nhà cung cấp nổi tiếng về lao động cưỡng bức hay bóc lột. Tôi ưu tiên những nhà làm nghề có chuỗi cung ứng minh bạch và đối xử công bằng với người thợ. Bản tuyên bố đầy đủ hơn có sẵn theo yêu cầu.","eco.brands.h":"Những thương hiệu Việt có ý thức tôi có thể tìm nguồn","eco.th1":"Thương hiệu","eco.th2":"Vì sao có ý thức","eco.cat.clothing":"Quần áo &amp; vải vóc","eco.b.metiseko":"Cotton hữu cơ chuẩn GOTS &amp; lụa Việt Nam, nhuộm ít tác động, sản xuất số lượng nhỏ (Hội An).","eco.b.moidien":"Thương hiệu thiết kế Sài Gòn; bền &amp; \"mua chất hơn, giữ lâu hơn\".","eco.b.timtay":"Sợi tự nhiên với kỹ thuật cắt không lãng phí (Hồ Chí Minh).","eco.b.f4f":"Chuỗi cung ứng trực tiếp từ nghệ nhân, minh bạch triệt để (Huế).","eco.b.archive":"Vá &amp; tái chế kiểu Boro / Sashiko — những món độc bản (Đà Lạt).","eco.b.the31":"Thời trang nữ hiện đại sử dụng vật liệu tái chế &amp; ít tác động hơn.","eco.b.boo":"Streetwear với thực hành bền vững rõ ràng &amp; lượng người theo dõi nội địa mạnh mẽ.","eco.b.hanoi":"Nhuộm tự nhiên, sợi bản địa, nghề thủ công của nghệ nhân (Hanoi).","eco.cat.shoes":"Giày","eco.b.tnbhsg":"Atelier Sài Gòn (thành lập 2018), giày da làm thủ công.","eco.b.gogrunge":"Giày làm thủ công tại Sài Gòn, gìn giữ nghề đóng giày địa phương.","eco.b.rens":"Giày sneaker tại Việt Nam làm từ vật liệu sáng tạo từ bã cà phê.","eco.cat.eyewear":"Kính mắt","eco.b.seeson":"Kính mắt Việt Nam làm từ acetate cellulose gốc sinh học, thiết kế hiện đại.","eco.cat.accessories":"Phụ kiện &amp; túi xách","eco.b.leinne":"Phụ kiện xa xỉ bền vững của Sài Gòn với bản sắc Việt đậm nét.","eco.b.dongdong":"Túi từ vật liệu tái sử dụng — giảm thiểu, tái sử dụng, tái chế.","eco.b.losilk":"Thời trang chậm made-in-Sài Gòn; khăn lụa tinh tế &amp; phụ kiện mềm mại.","eco.vintage.h":"Đồ secondhand &amp; vintage cao cấp tại Sài Gòn","eco.vintage.b":"Để mua sắm tuần hoàn, tôi có thể săn tìm đồ cũ tuyển chọn — ví dụ Maintwo (Q1), The Normal (Thủ Đức), 2Abnormal, Mayhem, Hebe Vintage, các cửa hàng Nhật Tảo (Q10), và các sạp ở chợ Bà Chiểu &amp; Chợ Bàn Cờ. Hàng hiệu secondhand qua ký gửi đã xác minh theo yêu cầu.","eco.reading":"Bài đọc thêm","inq.eyebrow":"Bắt đầu yêu cầu của bạn","inq.h2":"Cho tôi biết bạn đang tìm gì","inq.intro":"Bạn chia sẻ càng nhiều, tôi càng tìm được nhanh và gửi cho bạn một báo giá trung thực. Chưa cần thanh toán — đây chỉ đơn giản là khởi đầu của cuộc trò chuyện với Sài Gòn.","inq.step1":"Bạn đang tìm gì","inq.step2":"Độ vừa vặn &amp; giao hàng (không bắt buộc)","inq.step3":"Cách liên hệ với bạn","inq.name":"Tên","inq.email":"Email","inq.country":"Quốc gia / nơi nhận","inq.budget":"Ngân sách","inq.budget.ph":"ví dụ $150","inq.looking":"Bạn đang tìm gì","inq.looking.ph":"Một đường dẫn, một thương hiệu, hay chỉ cần cảm hứng — coquette, áo dài cách tân, vintage, làm đẹp…","inq.size":"Size &amp; số đo","inq.timeline":"Thời hạn","inq.inspo":"Đường dẫn cảm hứng (không bắt buộc)","inq.notes":"Điều gì khác nữa","inq.submit":"Gửi yêu cầu của tôi","inq.sent":"✓ Đang mở ứng dụng email với mọi thứ đã điền sẵn. Hoặc nhắn tin cho tôi trên Instagram.","inq.privacy":"Số đo, ảnh và địa chỉ của bạn được giữ riêng tư — chỉ dùng để tìm nguồn và gửi đơn hàng, không bao giờ chia sẻ hay bán đi.","inq.response":"Tôi thường trả lời trong 1–2 ngày làm việc (giờ Sài Gòn, GMT+7).","inq.or":"Muốn liên hệ trực tiếp? Instagram, TikTok và email đều luôn mở.","inq.estlink":"Lập ước tính trước","foot.biz":"Tạo phong cách &amp; tìm nguồn cá nhân cho thời trang và làm đẹp Việt Nam.<br/>Đặt tại Hồ Chí Minh, Việt Nam.<br/>Phản hồi trong 1–2 ngày làm việc (GMT+7).","foot.explore":"Khám phá","foot.gift":"Quà tặng phong cách","foot.sizing":"Kích cỡ &amp; dáng mặc","foot.legal":"Trợ giúp &amp; pháp lý","foot.eco":"Bền vững &amp; đạo đức","foot.connect":"Kết nối","foot.linkhub":"Trung tâm liên kết","foot.chat":"WhatsApp &amp; Zalo theo yêu cầu","foot.tagline":"Phong cách Sài Gòn, giao đến mọi nơi.","hero.ctaGo":"Bắt đầu yêu cầu","look.h2b":"Những dự án gần đây","look.intro2":"Những món đồ Việt được tìm mua cho khách hàng trên khắp thế giới — cùng các trang phục được phối riêng theo yêu cầu, từ $235.","hero.ctaSource":"Tìm mua một món đồ","hero.ctaStyle2":"Đặt dịch vụ phối đồ · từ $235","hero.lead2b":"Mỗi món đồ đều được <mark class=\"hl\">kiểm tra trực tiếp</mark> trước khi gửi đi.","hero.assure3":"<a href=\"#directory\" style=\"color:inherit\">320 thương hiệu đã được kiểm tra trực tiếp</a> · phản hồi trong một ngày làm việc","svc2.h2":"Hai cách làm việc cùng mình","svc2.laneA":"Tìm mua — bạn đã chọn món đồ","svc.1a":"Món đồ cụ thể bạn chọn, được tìm mua tại Sài Gòn và kiểm tra trực tiếp.","svc.1b2":"Gửi đường dẫn, kích cỡ và nơi nhận — mình chụp ảnh để bạn duyệt trước khi mua, trong 1–3 ngày.","svc.1p":"Giá cửa hàng + phí tìm mua + phí vận chuyển","svc.7a":"Mỹ phẩm và sản phẩm chăm sóc da sản xuất tại Việt Nam, ít được bán ở nước ngoài.","svc.7b2":"Kiểm tra niêm phong và thông tin lô sản xuất; lưu ý quy định hải quan trước khi mua.","svc.7p":"Giá sản phẩm + phí tìm mua + phí vận chuyển","svc2.findh":"Tìm nguồn món đồ bạn đã thấy","svc2.finda":"Dành cho món đồ bạn đã thấy nhưng chưa biết nguồn.","svc2.findb3":"Gửi ảnh chụp màn hình; mình tìm shop, nhắn shop bằng tiếng Việt, xác nhận size, màu, kiểu và báo giá bằng USD.","svc2.findb2":"Gửi ảnh; mình tìm thương hiệu, nhắn shop bằng tiếng Việt, theo dõi đến khi shop trả lời và báo giá bằng USD.","svc2.findp":"The Trace — $50 mỗi món, cho phần tìm kiếm","svc2.findcta":"Bắt đầu với The Trace","svc2.laneB":"Phối đồ — mình lựa chọn cho bạn","svc2.t1h":"The Discovery — $49","svc2.t1a":"Một lần định hướng phong cách đầu tiên, hoặc một món quà chu đáo.","svc2.t1b2":"Lựa chọn 1–2 món đồ cho bạn.","svc2.t1p":"$15 phí phối đồ + $34 ngân sách mua đồ","svc2.t1cta":"Đặt The Discovery","svc2.t2h":"The Edit — $235","svc2.t2a":"Định hướng phong cách rõ hơn, với nhiều lựa chọn để cân nhắc.","svc2.t2b2":"Thường gồm 3–5 món, được chụp ảnh kèm giá thực tế để bạn duyệt.","svc2.t2p":"$135 phí phối đồ + $100 ngân sách mua đồ","svc2.t2cta":"Đặt The Edit","svc2.t3h":"The Capsule — $460","svc2.t3a":"Một tủ đồ gọn, với các món được chọn để phối cùng nhau.","svc2.t3b2":"Thường gồm 8–12 món dễ phối và mặc nhiều lớp, kèm cẩm nang phối đồ.","svc2.t3p":"$270 phí phối đồ + $190 ngân sách mua đồ","svc2.t3cta":"Đặt The Capsule","svc2.t4h":"The Atelier — $600","svc2.t4a":"Trải nghiệm đầy đủ hơn — trao đổi sâu hơn, tinh chỉnh kỹ hơn.","svc2.t4b2":"Tại Sài Gòn hoặc qua cuộc gọi video trực tiếp.","svc2.t4p":"$310 phí phối đồ + $290 ngân sách mua đồ","svc2.t4cta":"Đặt The Atelier","svc2.t5h":"The Signature — $790","svc2.t5a":"Dịch vụ đặt thiết kế — Fancì Club, GIA Studios và các atelier.","svc2.t5b2":"Thử đồ may theo số đo, cẩm nang phối đồ và 60 ngày hỗ trợ.","svc2.t5p":"$310 phí phối đồ + $480 ngân sách mua quần áo","svc2.t5book":"Đặt The Signature","svc2.t5cta2":"hoặc đọc thông tin đầy đủ trước","step.1b2":"Gửi đường dẫn, ảnh chụp màn hình hoặc ảnh món đồ — mình sẽ đánh giá thẳng thắn khả năng tìm mua.","step.2h2":"Thông tin đơn hàng","step.2b2":"Kích cỡ, ngân sách và nơi nhận — đối chiếu với bảng kích cỡ của chính thương hiệu.","step.7b2":"Sau khi hàng đến, mình hỏi thăm để chắc rằng mọi thứ đều ổn.","inq2.eyebrow":"Bắt đầu","inq2.h2":"Chọn dịch vụ phù hợp","inq2.intro":"Món đồ cụ thể được mua theo giá gốc cộng phí dịch vụ rõ ràng. Phối đồ cá nhân — định hướng, tuyển chọn và xây dựng tủ đồ gọn — là dịch vụ trả phí từ $49, với phần lớn khoản đặt dịch vụ được dành để mua đồ. Chọn dịch vụ phù hợp; mình sẽ phản hồi trong một ngày làm việc.","inq2.src":"Tìm mua một món đồ","inq2.srcSub":"Bạn biết món đồ, thương hiệu hoặc cửa hàng — mình tìm mua, kiểm tra trực tiếp và gửi đi.","inq2.sty":"Đặt dịch vụ phối đồ","inq2.stySub":"Định hướng trang phục, tuyển chọn và xây dựng tủ đồ gọn — từ $49, có ngân sách dành để mua đồ.","inq2.blk":"Đơn nhóm và số lượng lớn","inq2.blkSub":"Dành cho văn phòng, sự kiện và bạn bè đặt hàng cùng nhau.","inq2.moodnote":"Bạn gửi ảnh cảm hứng hoặc bảng ý tưởng? Đây là dịch vụ phối đồ — bắt đầu với Discovery, $49.","inq2.giftlink":"Tặng một trải nghiệm phối đồ","gr.badge":"Sử dụng mã quà tặng","gr.pageh":"Sử dụng món quà của bạn","gr.pagesub":"Bạn được tặng một món quà Seraphic Styler. Tại đây, bạn có thể xem rõ chi phí khi sử dụng quà tặng cho những món đồ mình đang cân nhắc. Khi sẵn sàng, hãy gửi mã quà tặng và lựa chọn của bạn — đường dẫn, ảnh hoặc hồ sơ phong cách — mình sẽ hỗ trợ các bước tiếp theo.","ui.on":"Bật","ui.off":"Tắt","ui.menu":"Danh mục","dir.houses":"Các nhà mốt","dir.sig":"✦ Xem 24 nhà Signature →","est.items.hint":"Chưa có món đồ nào — bạn vẫn có thể thêm một gói phối đồ ở bước 3.","est.stops":"Mình cần ghé bao nhiêu cửa hàng?","est.stops.help":"Hai điểm đầu đã bao gồm trong phí. Mỗi cửa hàng thêm tính 150,000₫ — việc đi tìm qua nhiều quận cần thêm thời gian.","est.stops.o1":"1–2 cửa hàng — đã bao gồm","est.stops.o2":"3 cửa hàng (+150,000₫)","est.stops.o3":"4 cửa hàng (+300,000₫)","est.stops.o4":"5 cửa hàng (+450,000₫)","est.stops.o5":"6+ cửa hàng (+600,000₫, xác nhận trước với bạn)","est.complex.tip3":"Chỉ áp dụng cho món hiếm hoặc đợt mở bán giới hạn, thời hạn gấp, hoặc nhiều thay đổi sau khi bắt đầu tìm mua — luôn được thống nhất trước với bạn.","est.styling":"Thêm dịch vụ phối đồ? (không bắt buộc)","est.styling.help":"Mua một món bạn đã tìm được chỉ tính phí tìm mua. Nếu muốn thêm buổi tư vấn hoặc một bộ tuyển chọn, hãy thêm gói phối đồ tại đây — cùng mức giá với các gói quà tặng, mỗi gói có ngân sách mua đồ được trừ trực tiếp vào các món bên dưới. Thao tác này chỉ thêm vào ước tính; mình vẫn trao đổi qua tin nhắn để xác nhận và đặt dịch vụ cùng bạn.","est.styling.none":"Không phối đồ — chỉ tìm mua các món của mình","est.styling.discovery2":"The Discovery — định hướng phong cách đầu tiên, chọn 1–2 món (+$49, gồm 850,000₫ ngân sách mua đồ)","est.pay":"Bạn muốn thanh toán bằng cách nào?","est.pay.help":"Chuyển khoản, Wise và Zelle không có phí xử lý thẻ. Thanh toán thẻ qua Stripe có phí xử lý — hiển thị thành một dòng riêng, không ẩn trong giá. Với mọi phương thức, khoản dự trù 3% cho việc chuyển tiền vào Việt Nam cũng được ghi riêng, theo chi phí thực tế và không cộng thêm lợi nhuận.","est.pay.bank":"Chuyển khoản / Wise / Zelle — không có phí thẻ","est.pay.card":"Thẻ qua Stripe — thêm khoảng 5.4% + $0.30 (mức quốc tế)","est.fee.tip2":"Phí tìm mua mỗi món: 8% giá món đồ (7% nếu trên 5,000,000₫), tối thiểu 500,000₫ mỗi món. Đã bao gồm vận chuyển nội địa Việt Nam.","est.base.tip2":"250,000₫ cố định cho mỗi đơn, gồm điều phối, đi lại, trao đổi và đóng gói cẩn thận. Phí vận chuyển được tính theo chi phí thực tế.","est.styleline":"Dịch vụ phối đồ","est.style.tip":"Buổi tư vấn hoặc bộ tuyển chọn tùy chọn — cùng gói và giá như quà tặng (Discovery $49, Edit $149, Capsule $249, Atelier $349). Mỗi gói có ngân sách mua đồ ($34 / $104 / $174 / $239), hiển thị riêng bên dưới. Món đồ vẫn tính theo giá gốc; vận chuyển tính riêng.","est.creditline":"Ngân sách mua đồ đã áp dụng","est.credit.tip":"Mỗi gói phối đồ có một khoản ngân sách mua đồ cố định — cùng khoản có trong gói quà tặng ($100 / $190 / $290). Khoản này được trừ tại đây, tối đa bằng tổng giá trị các món đồ.","est.leftoverline":"Ngân sách quà tặng còn lại","est.leftover.tip":"Phần ngân sách chưa dùng không mất đi — được giữ lại trong quà tặng cho đơn sau. Nhắc mình khi gửi yêu cầu tiếp theo để áp dụng trước khi mua.","est.stopsline":"Điểm ghé thêm","est.stops.tip":"Hai cửa hàng đầu đã bao gồm trong phí dịch vụ. Mỗi cửa hàng thêm trong danh sách tính 150,000₫ cho thời gian và đi lại — luôn thống nhất trước khi mình lên đường.","est.fxline":"Chuyển tiền (3%)","est.fx.tip":"Chuyển khoản thanh toán vào Việt Nam có chi phí thực tế — phí chuyển tiền của Wise. Khoản dự trù nhỏ này bù chi phí, không cộng thêm lợi nhuận; chênh lệch được đối chiếu trong báo giá bằng văn bản. Áp dụng cho mọi phương thức thanh toán.","est.cardline":"Xử lý thẻ (Stripe)","est.card.tip":"Tính theo chi phí thực tế, không cộng thêm lợi nhuận. Stripe thu 2.9% + $0.30, thêm 1.5% cho thẻ quốc tế và 1% khi chuyển đổi tiền tệ. Ước tính chưa xác định được loại thẻ nên dùng mức quốc tế đầy đủ — đây là mức trần. Nếu thẻ của bạn là thẻ nội địa, số tiền trên đường dẫn thanh toán sẽ thấp hơn. Chuyển khoản, Wise và Zelle không có phí xử lý thẻ; dòng chuyển tiền 3% áp dụng cho việc chuyển tiền vào Việt Nam với mọi phương thức.","est.split.card":"Xử lý thẻ","est.split.deptotal":"Tổng tiền đặt cọc khi trả bằng thẻ","est.split.baltotal":"Tổng số dư khi trả bằng thẻ","est.empty":"Chưa có gì để ước tính — hãy thêm giá món đồ hoặc chọn một gói phối đồ.","est.acc.sum":"Ước tính này chính xác đến đâu?","est.acc.p1":"<strong>Khoảng 95% là phần xác định được.</strong> Giá món đồ bạn nhập, phí dịch vụ và phí cơ bản cố định được tính theo công thức — phép tính trên dữ liệu bạn nhập là chính xác, và vận chuyển nội địa Việt Nam đã được bao gồm.","est.acc.complex":"<strong>Một khoản có thể phát sinh:</strong> 200,000₫ cố định cho yêu cầu tìm mua món hiếm hoặc qua nhiều cửa hàng — đợt mở bán khó tìm, nhiều điểm ghé hoặc thời hạn gấp. Luôn thống nhất trước với bạn, không bất ngờ thêm vào báo giá cuối.","est.acc.p2":"<strong>Khoảng 5% còn lại được xác nhận trước khi bạn trả tiền:</strong> giá thực tế tại cửa hàng hôm mua, phí gửi quốc tế chính xác (cân nặng và đơn vị vận chuyển), tỷ giá hiện tại, tình trạng hàng và thuế hoặc phí hải quan tại nước nhận.","est.acc.p3":"Không thu tiền trước khi bạn duyệt báo giá cuối.","est.share.h":"Đường dẫn xem trước cho khách hàng","est.share.s":"Mở đúng ước tính hiện tại — cùng dữ liệu nhập và tỷ giá — ngay trên trang này. Đường dẫn có hiệu lực 24 giờ rồi hết hạn.","est.share.copy":"Sao chép","est.preview.btn":"Tạo đường dẫn xem trước có hiệu lực 24 giờ","est.faq.eyebrow":"Trước khi gửi","est.faq.h2":"Giải đáp những điều bạn cần biết","est.faq.q1":"Đây có phải báo giá không? Mình có đang cam kết đặt hàng không?","est.faq.a1":"Không. Ước tính là phép tính, chưa phải đơn hàng — không tìm mua, giữ hàng hay thu tiền cho đến khi bạn duyệt báo giá cuối do mình xác nhận trực tiếp.","est.faq.q2":"Điều gì xảy ra sau khi mình bấm gửi?","est.faq.a2":"Mình nhận bản tóm tắt qua biểu mẫu; một bản sao cũng được lưu vào bộ nhớ tạm của bạn để dự phòng. Trong vòng một ngày, mình phản hồi giá thực tế, tình trạng hàng và phí gửi chính xác tới địa chỉ của bạn — đó là báo giá cuối.","est.faq.q3":"Khi nào mình thực sự thanh toán?","est.faq.a3":"Sau khi bạn duyệt báo giá cuối, thanh toán chia làm hai phần: đặt cọc gồm tiền đồ và phí để mình mua hàng, rồi thanh toán phí vận chuyển sau khi kiện hàng được đóng gói và cân. Như vậy, phí gửi là giá thực tế của đơn vị vận chuyển. Trang này không yêu cầu bạn thanh toán.","est.faq.q4":"Thanh toán có an toàn không?","est.faq.a4":"Chuyển khoản, Wise, PayPal hoặc Payoneer — chọn PayPal Goods &amp; Services nếu muốn có cơ chế bảo vệ người mua. Bạn nhận ảnh xác nhận của từng món trước khi gửi và mã theo dõi ngay khi hàng được gửi đi.","est.faq.q5":"Vì sao phí vận chuyển chiếm phần lớn tổng tiền?","est.faq.a5":"Đơn vị vận chuyển tính theo cân nặng và thể tích; cước quốc tế thực tế vốn cao — một kiện 0.5–1&nbsp;kg gần đây có phí 1,950,000₫. Phí gửi được tính đúng chi phí, không cộng thêm lợi nhuận, và mình đóng gói lại cẩn thận để giảm thể tích tính cước.","est.faq.q6":"Nếu đồ không vừa hoặc nhận nhầm hàng thì sao?","est.faq.a6":"Kích cỡ được đối chiếu với số đo thực tế của món đồ trước khi mua — đây là một phần dịch vụ. Nếu nhận sai món hoặc hàng hư hỏng, hãy báo mình trong 48 giờ kèm video mở kiện để mình xử lý."});
